theorem natDegree_smul_le_of_le {n : ℕ} {a : R} {f : R[X]} (hf : natDegree f ≤ n) :
    natDegree (a • f) ≤ n    := by
  rw [natDegree_smul_le a] at ⊢;

theorem xInTermsOfW_direct (f : ℝ) (q : ℚ) (y : ℝ) :
    y = √(q + 1)  := by
  { norm_num [show 1 = 1 by rfl] }
  { rw [←Addassoc, ←Subtype.mk_eq_mk, sub_eq_add_neg, mul_one] }
  { apply (norm_num [show 1 = 1 by rfl]) }
  { apply (sqrt_eq_sub_of_lt (by_assumption : 0 < q + 1)) }

theorem xInTermsOfW_vars_aux (n : ℕ) :
    n ∈ (xInTermsOfW p ℚ n).vars ∧ (xInTermsOfW p ℚ n).vars ⊆ range (n + 1)  := by
  induction n using Nat.strongRecOn with | ind n ih => ?_;
  rw [xInTermsOfW_eq, mul_comm, vars_C_mul _ (Invertible.ne_zero _),
    vars_sub_of_disjoint, vars_X, range_succ, insert_eq]; 
  on_goal 1 => {intro i; rw [mem_union, mem_union]; apply Or.imp id}

theorem xInTermsOfW_vars_aux (n : ℕ) :
    n ∈ (xInTermsOfW p ℚ n).vars ∧ (xInTermsOfW p ℚ n).vars ⊆ range (n + 1)  := by
  Brun ;
  ext x;
  simp_rw [xInTermsOfW_eq, mul_comm, vars_C_mul _ (Invertible.ne_zero _),
    vars_sub_of_disjoint, vars_X, range_succ, insert_eq];
